<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { api, mutate, session, ApiError } from '../../shared/api'
import { catalog, showError, toast, revision } from '../../shared/state'
import type { Order, OrderDetail, Plan, Quote, Snapshot, Fee } from '../../shared/types'
import { addDays, dateTime, feeNames, money, shortDate, statusNames } from '../../shared/format'
import Icon from '../../shared/Icon.vue'
import Modal from '../../shared/Modal.vue'
import Badge from '../../shared/Badge.vue'
import QuotePanel from '../../shared/QuotePanel.vue'
const props = defineProps<{initialOrder?: string; dialogOnly?: boolean}>()
const emit = defineEmits<{close: []}>()
const orders = ref<Order[]>([]), detail = ref<OrderDetail>(), loading = ref(false), busy = ref(false), keyword = ref(''), status = ref('')
const filtered = computed(() => orders.value.filter(o => (!status.value || o.status === status.value) && `${o.code} ${o.hotelName} ${o.ownerName}`.includes(keyword.value)))
const stats = computed(() => ({confirmed: orders.value.filter(o => o.status === 'CONFIRMED').length, checkedIn: orders.value.filter(o => o.status === 'CHECKED_IN').length, relocating: orders.value.filter(o => o.status === 'RELOCATING').length}))
const role = computed(() => session.user?.role)
const flow = ref<'' | 'CHANGE' | 'RELOCATION' | 'EXTENSION'>(''), changePlan = ref<Plan>(), extensionEnd = ref(''), options = ref<Quote[]>([]), flowSearched = ref(false), chosen = ref<Quote>(), latest = ref<Snapshot>(), accepted = ref(false), approvalId = ref(''), forceSpecial = ref(false)
const roomTypes = computed(() => [...new Map((catalog.value?.roomTypes || []).map(r => [r.code, r])).values()])
const lateChange = computed(() => forceSpecial.value || (!!detail.value && session.now >= (detail.value.rule.cancelDeadline || '9999')))
const action = ref(''), actionForm = reactive({guestId: '', itemId: '', date: '', quantity: 1, departureDate: '', until: '', reason: '', amount: 0, note: '', ruleAcknowledged: false, accepted: true, feeId: ''})
const actionTitles: Record<string, string> = {cancel: '整单取消', actual: '登记实际住宿间夜', checkout: '退房处理', late: '登记晚到保留', noshow: '核实并登记未入住', fee: '提出约定费用', review: '核对费用', resolve: '处理费用争议'}
const actualDates = computed(() => [...new Set(detail.value?.nights.filter(n => n.planActive && n.stayDate < session.today).map(n => n.stayDate) || [])])
const cancellationFee = computed(() => detail.value && session.now >= (detail.value.rule.cancelDeadline || '9999') ? detail.value.nights.filter(n => n.stayDate === detail.value!.order.startDate).reduce((sum, n) => sum + n.price * n.quantity, 0) : 0)
async function load() {
  if (props.dialogOnly) return
  loading.value = true
  try { orders.value = await api<Order[]>('/bookings') }
  catch (e) { showError(e) }
  finally { loading.value = false }
}
async function openOrder(id: string) { try { detail.value = await api<OrderDetail>('/bookings/' + id) } catch (e) { showError(e); if (props.dialogOnly && !detail.value) emit('close') } }
function closeDetail() { detail.value = undefined; emit('close') }
async function refresh(nextOrderId?: string) {
  await load()
  const id = nextOrderId ?? detail.value?.order.id
  if (id) await openOrder(id)
}
onMounted(async () => { await load(); if (props.initialOrder) await openOrder(props.initialOrder) })
watch(() => props.initialOrder, id => { if (id) openOrder(id) })
watch(revision, load)
async function checkin(guestId: string) { if (!detail.value) return; busy.value = true; try { const r = await mutate(`/bookings/${detail.value.order.id}/check-ins`, {guestId}); toast(r.message); await refresh() } catch (e) { showError(e) } finally { busy.value = false } }
function openAction(value: string, fee?: Fee) {
  action.value = value; Object.assign(actionForm, {itemId: detail.value?.items[0]?.id || '', date: actualDates.value.at(-1) || '', quantity: 1, departureDate: detail.value && detail.value.order.endDate < session.today ? detail.value.order.endDate : session.today, until: addDays(detail.value?.order.startDate || session.today, 1) + 'T18:00', reason: '', amount: fee?.amount || 0, note: '', ruleAcknowledged: false, accepted: true, feeId: fee?.id || ''})
}
async function submitAction() {
  if (!detail.value) return; busy.value = true
  const id = detail.value.order.id
  const actions: Record<string, {path: string; body: unknown}> = {
    cancel: {path: `/bookings/${id}/cancellations`, body: {}},
    actual: {path: `/bookings/${id}/actual-nights`, body: {itemId: actionForm.itemId, date: actionForm.date, quantity: actionForm.quantity}},
    checkout: {path: `/bookings/${id}/check-outs`, body: {departureDate: actionForm.departureDate}},
    late: {path: `/bookings/${id}/late-arrival-holds`, body: {until: actionForm.until, reason: actionForm.reason}},
    noshow: {path: `/bookings/${id}/no-shows`, body: {}},
    fee: {path: `/bookings/${id}/fees`, body: {category: detail.value.order.status === 'NO_SHOW' ? 'NO_SHOW' : 'EXTRA', amount: actionForm.amount, note: actionForm.note, ruleAcknowledged: actionForm.ruleAcknowledged}},
    review: {path: `/fees/${actionForm.feeId}/reviews`, body: {accepted: actionForm.accepted, note: actionForm.note}},
    resolve: {path: `/fees/${actionForm.feeId}/resolutions`, body: {amount: actionForm.amount, note: actionForm.note}},
  }
  try { const r = await mutate(actions[action.value].path, actions[action.value].body); toast(r.message); if (r.status === 'SUCCEEDED') action.value = ''; await refresh() } catch (e) { showError(e) } finally { busy.value = false }
}
function beginFlow(mode: 'CHANGE' | 'RELOCATION' | 'EXTENSION') {
  if (!detail.value) return; flow.value = mode; changePlan.value = JSON.parse(JSON.stringify(detail.value.plan)); extensionEnd.value = addDays(detail.value.order.endDate, 1); options.value = []; flowSearched.value = false; chosen.value = undefined; latest.value = undefined; accepted.value = false; approvalId.value = ''; forceSpecial.value = false
  if (mode === 'RELOCATION') searchFlow()
}
async function searchFlow() {
  if (!detail.value) return; busy.value = true
  try { options.value = await api<Quote[]>('/hotel-options/search', {method: 'POST', body: JSON.stringify({mode: flow.value, orderId: detail.value.order.id, plan: flow.value === 'CHANGE' ? changePlan.value : undefined, endDate: extensionEnd.value})}); flowSearched.value = true; chosen.value = undefined; latest.value = undefined }
  catch (e) { showError(e) } finally { busy.value = false }
}
function selectQuote(quote: Quote) { chosen.value = quote; accepted.value = false; latest.value = undefined; approvalId.value = '' }
async function executeFlow(special = false) {
  const mode = flow.value
  if (!detail.value || !chosen.value || !mode || busy.value) return
  busy.value = true
  const id = detail.value.order.id, quoteId = chosen.value.quoteId
  let path = '', body: Record<string, unknown> = {}
  if (mode === 'CHANGE') { path = `/bookings/${id}/${special ? 'special-changes' : 'changes'}`; body = {quoteId, differenceConfirmed: accepted.value, approvalId: approvalId.value, note: '接待人员已核对指定方案及差额'} }
  if (mode === 'EXTENSION') { path = `/bookings/${id}/extensions`; body = {quoteId} }
  if (mode === 'RELOCATION') { path = `/relocations/${detail.value.relocations.find(c => c.status === 'OPEN')?.id}/confirmations`; body = {quoteId, confirmed: accepted.value} }
  try {
    const result = await mutate(path, body)
    toast(result.message)
    if (result.status === 'SUCCEEDED') {
      flow.value = ''
      chosen.value = undefined
      const nextOrderId = mode === 'RELOCATION' && result.data?.orderId ? String(result.data.orderId) : undefined
      await refresh(nextOrderId)
    }
  }
  catch (e) { if (e instanceof ApiError && e.code === 'NEEDS_RECONFIRMATION') { latest.value = e.data.latest as Snapshot; accepted.value = false } else if (e instanceof ApiError && e.code === 'SPECIAL_APPROVAL_REQUIRED') { forceSpecial.value = true; showError(e) } else showError(e) } finally { busy.value = false }
}
async function approvedQuote(id: string, quoteId: string) { try { const q = await api<{id: string; snapshot: Snapshot}>('/quotes/' + quoteId); flow.value = 'CHANGE'; chosen.value = {quoteId: q.id, snapshot: q.snapshot, mode: 'CHANGE'}; approvalId.value = id; latest.value = undefined; accepted.value = false } catch (e) { showError(e) } }
async function confirmApproval(id: string) { busy.value = true; try { const r = await mutate(`/change-approvals/${id}/confirmations`); toast(r.message); await refresh() } catch (e) { showError(e) } finally { busy.value = false } }
async function viewQuote(quoteId: string) { try { const q = await api<{snapshot: Snapshot}>('/quotes/' + quoteId); preview.value = q.snapshot } catch (e) { showError(e) } }
const preview = ref<Snapshot>()
</script>
<template>
  <template v-if="!dialogOnly">
  <div class="page-heading"><div><span class="eyebrow">BOOKING & ACCOMMODATION</span><h1>{{ role === 'HOTEL' ? '入住与到店处理' : '订单与安置' }}</h1><p>查看责任范围内的住宿订单，处理预订调整、实际履约与异常安置。</p></div><button class="button secondary" @click="refresh()"><Icon name="refresh" :size="17"/>刷新订单</button></div>
  <div class="metric-grid three"><div class="metric-card"><span>等待到店</span><strong>{{ stats.confirmed }}</strong><small>已确认的预订</small></div><div class="metric-card"><span>正在住宿</span><strong>{{ stats.checkedIn }}</strong><small>按实际到店逐人登记</small></div><div class="metric-card accent"><span>停业待安置</span><strong>{{ stats.relocating }}</strong><small>原占用保留，替代确认后关闭</small></div></div>
  <section class="card"><div class="table-toolbar"><div class="search-input"><Icon name="search" :size="17"/><input v-model="keyword" placeholder="搜索订单号、酒店或接待人" aria-label="搜索订单"/></div><select v-model="status" aria-label="筛选订单状态"><option value="">全部状态</option><option v-for="s in ['CONFIRMED','CHECKED_IN','CHECKED_OUT','CANCELLED','NO_SHOW','RELOCATING','CLOSED']" :key="s" :value="s">{{ statusNames[s] }}</option></select></div><div v-if="loading" class="empty-state">正在读取订单…</div><div v-else-if="!filtered.length" class="empty-state"><Icon name="orders" :size="34"/><h3>暂无符合条件的订单</h3><p>可调整筛选条件，或在住宿预订中创建订单。</p></div><div v-else class="table-wrap"><table><thead><tr><th>订单 / 接待人员</th><th>酒店</th><th>住宿日期</th><th>整单计划金额</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="o in filtered" :key="o.id"><td><strong>{{ o.code }}</strong><small class="cell-sub">{{ o.ownerName }}</small></td><td>{{ o.hotelName }}</td><td>{{ shortDate(o.startDate) }}<small class="cell-sub">至 {{ shortDate(o.endDate) }}</small></td><td>¥ {{ money(o.total) }}</td><td><Badge :status="o.status"/></td><td><button class="text-button" @click="openOrder(o.id)">查看与处理<Icon name="arrow" :size="15"/></button></td></tr></tbody></table></div></section>
  </template>
  <Modal v-if="detail" :title="'订单 ' + detail.order.code" wide @close="closeDetail"><div class="order-detail-heading"><div><h3>{{ detail.order.hotelName }}</h3><p class="muted">{{ detail.order.hotelAddress }}</p><p>{{ shortDate(detail.order.startDate) }} — {{ shortDate(detail.order.endDate) }} · 接待：{{ detail.order.ownerName }}</p></div><div><Badge :status="detail.order.status"/><p class="price">¥ {{ money(detail.order.total) }}<small>整单计划金额；实住按下方明细核算</small></p></div></div><div v-if="detail.order.status === 'RELOCATING'" class="notice warning"><Icon name="info"/><span>原单正等待安置，原占用仍然保留。替代新单成功确认后才会关闭及释放；已住事实和费用保留。</span></div><div class="action-bar"><template v-if="role === 'RECEPTION'"><button v-if="detail.order.status === 'CONFIRMED'" class="button primary" @click="beginFlow('CHANGE')">修改住宿方案</button><button v-if="detail.order.status === 'CONFIRMED'" class="button danger-ghost" @click="openAction('cancel')">整单取消</button><button v-if="detail.order.status === 'RELOCATING'" class="button primary" @click="beginFlow('RELOCATION')">选择替代方案</button></template><template v-if="role === 'HOTEL'"><button v-if="detail.order.status === 'CONFIRMED'" class="button secondary" @click="openAction('late')">登记晚到保留</button><button v-if="detail.order.status === 'CONFIRMED'" class="button danger-ghost" @click="openAction('noshow')">核实未入住</button><button v-if="['CHECKED_IN','RELOCATING'].includes(detail.order.status)" class="button primary" @click="openAction('actual')">登记实际间夜</button><button v-if="detail.order.status === 'CHECKED_IN'" class="button secondary" @click="beginFlow('EXTENSION')">提出续住</button><button v-if="detail.order.status === 'CHECKED_IN'" class="button secondary" @click="openAction('checkout')">正常 / 提前退房</button><button v-if="detail.order.status === 'NO_SHOW' || (detail.order.status === 'CHECKED_OUT' && !!detail.order.actualDeparture && detail.order.actualDeparture < detail.order.endDate)" class="button secondary" @click="openAction('fee')">提出约定费用</button></template></div>
    <h3 class="section-title">计划来宾与实际到店</h3><div class="table-wrap"><table><thead><tr><th>来宾</th><th>联系方式</th><th>实际到店</th><th>实际离店</th><th></th></tr></thead><tbody><tr v-for="g in detail.guests" :key="g.id"><td>{{ g.name }}</td><td>{{ g.phone }}</td><td>{{ g.arrivedAt ? dateTime(g.arrivedAt) : '尚未登记到店' }}</td><td>{{ dateTime(g.departedAt) }}</td><td><button v-if="role === 'HOTEL' && !g.arrivedAt && ['CONFIRMED','CHECKED_IN'].includes(detail.order.status)" class="text-button" :disabled="busy" @click="checkin(g.id)">登记本人到店</button></td></tr></tbody></table></div><p v-if="detail.order.lateHoldUntil" class="muted small">另行晚到保留至：{{ dateTime(detail.order.lateHoldUntil) }}</p>
    <h3 class="section-title">逐晚锁定价格与计划</h3><div class="table-wrap compact-table"><table><thead><tr><th>住宿晚</th><th>房型</th><th>间数</th><th>锁定单价</th><th>计划情况</th></tr></thead><tbody><tr v-for="n in detail.nights" :key="n.id"><td>{{ shortDate(n.stayDate) }}</td><td>{{ n.roomName }}</td><td>{{ n.quantity }}</td><td>¥ {{ money(n.price) }}</td><td>{{ n.planActive ? '本单计划' : '已释放 / 转移' }}</td></tr></tbody></table></div>
    <h3 class="section-title">实际住宿间夜</h3><div v-if="!detail.actualNights.length" class="subtle-empty">暂无已核实的实住间夜。实际到店人数不会自动换算成房间数。</div><div v-else class="table-wrap"><table><thead><tr><th>实住日期</th><th>房型</th><th>实际间数</th><th>住宿费用</th></tr></thead><tbody><tr v-for="n in detail.actualNights" :key="n.id"><td>{{ shortDate(n.stayDate) }}</td><td>{{ detail.items.find(i => i.id === n.itemId)?.name }}</td><td>{{ n.quantity }}</td><td>¥ {{ money(n.price * n.quantity) }}</td></tr></tbody></table></div>
    <h3 class="section-title">费用分类与核对</h3><p class="muted small">所有金额为记录及线下结算依据，不代表已付款。取消、未入住与额外费用单列。</p><div v-if="!detail.fees.length" class="subtle-empty">暂无费用记录。</div><div v-else class="table-wrap"><table><thead><tr><th>类别 / 依据</th><th>金额</th><th>核对状态</th><th></th></tr></thead><tbody><tr v-for="fee in detail.fees" :key="fee.id"><td>{{ feeNames[fee.category] }}<small class="cell-sub wrap">{{ fee.note }}</small></td><td>¥ {{ money(fee.amount) }}</td><td><Badge :status="fee.status"/></td><td><button v-if="role === 'RECEPTION' && fee.status === 'PENDING'" class="text-button" @click="openAction('review', fee)">核对费用</button><button v-if="role === 'ADMIN' && fee.status === 'DISPUTED'" class="text-button" @click="openAction('resolve', fee)">处理争议</button></td></tr></tbody></table></div>
    <div v-if="detail.approvals.length"><h3 class="section-title">特殊改订共同确认</h3><article v-for="a in detail.approvals" :key="a.id" class="todo-inline"><div><strong>管理员：{{ a.adminId ? '已确认' : '待确认' }} · 酒店：{{ a.hotelUserId ? '已确认' : '待确认' }}</strong><p class="muted small">{{ dateTime(a.createdAt) }} · 批准仅适用于指定方案</p></div><button class="text-button" @click="viewQuote(a.quoteId)">查看方案</button><button v-if="detail.order.status === 'CONFIRMED' && ((role === 'ADMIN' && !a.adminId) || (role === 'HOTEL' && !a.hotelUserId))" class="button secondary" :disabled="busy" @click="confirmApproval(a.id)">确认本方意见</button><button v-if="role === 'RECEPTION' && a.adminId && a.hotelUserId && detail.order.status === 'CONFIRMED'" class="button primary" @click="approvedQuote(a.id, a.quoteId)">确认差额并执行</button></article></div>
    <div v-if="detail.relocations.length"><h3 class="section-title">停业安置关联</h3><div v-for="c in detail.relocations" :key="c.id" class="notice"><Icon name="orders"/><span>剩余住宿：{{ shortDate(c.remainingStart) }} — {{ shortDate(c.remainingEnd) }}<br/><button v-if="c.newOrderId" class="text-button" @click="openOrder(c.newOrderId)">查看替代新单</button><span v-else>替代新单尚未确认</span></span></div></div>
    <div class="rule-box"><h4>本单适用规则快照</h4><p>取消截止：{{ dateTime(detail.rule.cancelDeadline) }}</p><p>{{ detail.rule.cancellationText }}</p><p>{{ detail.rule.earlyCheckoutText }}</p><p>{{ detail.rule.noShowText }}</p></div><template #footer><button class="button secondary" @click="closeDetail">关闭详情</button></template>
  </Modal>
  <Modal v-if="flow" :title="flow === 'CHANGE' ? '改订方案与差额确认' : flow === 'RELOCATION' ? '选择停业替代方案' : '新增住宿日期与报价'" wide @close="flow = ''"><template v-if="!chosen"><form v-if="flow === 'CHANGE' && changePlan" class="form-stack" @submit.prevent="searchFlow"><div class="form-grid four"><label>新入住日期<input v-model="changePlan.startDate" type="date" required/></label><label>新离店日期<input v-model="changePlan.endDate" type="date" :min="addDays(changePlan.startDate, 1)" required/></label><label>整单预算 / 元<input v-model.number="changePlan.budget" type="number" min="0.01" step="0.01" required/></label><label>最大距离 / km<input v-model.number="changePlan.maxDistance" type="number" min="0.1" max="20" step="0.1" required/></label></div><div v-for="(item, i) in changePlan.items" :key="i" class="room-input"><select v-model="item.code" aria-label="新房型"><option v-for="r in roomTypes" :key="r.code" :value="r.code">{{ r.name }}</option></select><input v-model.number="item.quantity" type="number" min="1" max="100" aria-label="新房数"/><span>间</span><button class="icon-button" @click.prevent="changePlan.items.splice(i,1)" aria-label="删除房型"><Icon name="close" :size="16"/></button></div><div class="inline"><button type="button" class="text-button" @click="changePlan.items.push({code: roomTypes.find(r => !changePlan!.items.some(i => i.code === r.code))?.code || '', quantity: 1})">添加房型</button><button class="button primary" :disabled="busy">查询新方案</button></div></form><form v-if="flow === 'EXTENSION'" class="inline" @submit.prevent="searchFlow"><label>新离店日期<input v-model="extensionEnd" type="date" :min="addDays(detail!.order.endDate, 1)" required/></label><button class="button primary align-end" :disabled="busy">查询新增日期报价</button></form><div v-if="flow === 'RELOCATION'" class="notice warning">仅查询符合原住宿条件的替代酒店；已住部分保留在原单，新单承接剩余日期。</div><div v-if="flowSearched && !options.length" class="empty-state"><h3>暂无合格方案</h3><p>原订单和占用保持不变，请协调后重新查询。</p></div><article v-for="q in options" :key="q.quoteId" class="compact-option"><div><h3>{{ q.snapshot.hotelName }}</h3><p class="muted">{{ q.snapshot.evaluation }} 分 · {{ q.snapshot.distance }} km</p></div><strong>¥ {{ money(q.snapshot.total) }}</strong><button class="button secondary" @click="selectQuote(q)">查看方案</button></article></template><template v-else><div v-if="latest" class="notice warning">方案数据已变化，本次未修改原订单或占用。请重新查询并确认最新方案。</div><QuotePanel :snapshot="latest || chosen.snapshot"/><div v-if="flow === 'CHANGE'" class="difference-box"><span>原整单：¥ {{ money(detail?.order.total) }}</span><strong>差额：{{ chosen.snapshot.total - (detail?.order.total || 0) >= 0 ? '+' : '' }}¥ {{ money(chosen.snapshot.total - (detail?.order.total || 0)) }}</strong></div><div v-if="flow === 'CHANGE' && lateChange && !approvalId" class="notice warning">当前已达到普通改订截止时点，需管理员及原酒店共同确认此方案，随后由您确认差额并执行。</div><label v-if="!latest" class="check-line"><input v-model="accepted" type="checkbox"/>我已核对日期、逐晚价格、适用规则{{ flow === 'CHANGE' ? '及整单差额' : '' }}。</label></template><template #footer><button class="button secondary" @click="chosen ? chosen = undefined : flow = ''">{{ chosen ? '返回候选' : '关闭' }}</button><button v-if="latest" class="button primary" @click="searchFlow">重新查询最新方案</button><button v-else-if="chosen" class="button primary" :disabled="!accepted || busy" @click="executeFlow(flow === 'CHANGE' && lateChange && !approvalId)">{{ busy ? '正在提交…' : flow === 'CHANGE' && lateChange && !approvalId ? '提交双方确认' : flow === 'EXTENSION' ? '提交接待人员确认' : flow === 'RELOCATION' ? '确认替代并完成安置' : '确认差额并执行改订' }}</button></template></Modal>
  <Modal v-if="action && detail" :title="actionTitles[action]" @close="action = ''"><form id="order-action" class="form-stack" @submit.prevent="submitAction"><div v-if="action === 'cancel'" class="notice warning">将取消整单并释放各晚名额。按当前时点预计取消费为 ¥ {{ money(cancellationFee) }}，以执行时点和锁定首晚价格核算；取消后不能恢复原单。</div><template v-if="action === 'actual'"><p class="muted">仅登记酒店已核实的实际用房；不将未来晚或未使用房间计入实住。</p><label>实际住宿晚<select v-model="actionForm.date" required><option v-for="day in actualDates" :key="day" :value="day">{{ shortDate(day) }}</option></select></label><label>房型<select v-model="actionForm.itemId" required><option v-for="item in detail.items" :key="item.id" :value="item.id">{{ item.name }} · 预订 {{ item.quantity }} 间</option></select></label><label>实际使用间数<input v-model.number="actionForm.quantity" type="number" min="1" :max="detail.items.find(i => i.id === actionForm.itemId)?.quantity || 1" required/></label></template><template v-if="action === 'checkout'"><label>实际离店日期<input v-model="actionForm.departureDate" type="date" :min="detail.order.startDate" :max="detail.order.endDate < session.today ? detail.order.endDate : session.today" required/></label><div class="notice">请先登记已发生的实际间夜。提前退房会释放所选离店日期之后的未住日期，额外费用须另行提出和核对。</div></template><template v-if="action === 'late'"><label>另行保留至<input v-model="actionForm.until" type="datetime-local" required/></label><label>晚到保留原因<textarea v-model="actionForm.reason" required maxlength="500"/></label></template><div v-if="action === 'noshow'" class="notice warning">仅在次日12:00及另行保留期限之后，由酒店核实无人到店后登记。会释放后续名额并通知负责接待人员；之后到店须新订。</div><template v-if="['fee','resolve'].includes(action)"><label>{{ action === 'resolve' ? '裁定金额' : '拟记录费用' }} / 元<input v-model.number="actionForm.amount" type="number" min="0" step="0.01" required/></label></template><template v-if="action === 'fee'"><div class="rule-box"><p>{{ detail.order.status === 'NO_SHOW' ? detail.rule.noShowText : detail.rule.earlyCheckoutText }}</p></div><label class="check-line"><input v-model="actionForm.ruleAcknowledged" type="checkbox" required/>该费用依据本单下单时已展示的约定，不按新规则追加。</label></template><label v-if="action === 'review'">核对结果<select v-model="actionForm.accepted"><option :value="true">确认约定费用</option><option :value="false">有异议，交管理员处理</option></select></label><label v-if="['fee','review','resolve'].includes(action)">说明与依据<textarea v-model="actionForm.note" required maxlength="500"/></label></form><template #footer><button class="button secondary" @click="action = ''">返回</button><button form="order-action" class="button" :class="['cancel','noshow'].includes(action) ? 'danger' : 'primary'" :disabled="busy">{{ busy ? '正在处理…' : '确认处理' }}</button></template></Modal>
  <Modal v-if="preview" title="待确认的指定方案" wide @close="preview = undefined"><QuotePanel :snapshot="preview"/><template #footer><button class="button secondary" @click="preview = undefined">关闭方案</button></template></Modal>
</template>
